#!/usr/bin/env python3
"""
Финальное расширение базы знаний RAG - последняя партия
Добавляет 80+ Q&A для достижения цели 681+ документов
"""

import os
import sys
sys.path.insert(0, '/app')

from rag.supabase_manager import SupabaseRAGManager
from dotenv import load_dotenv

load_dotenv()

def main():
    print("=" * 60)
    print("ФИНАЛЬНОЕ РАСШИРЕНИЕ БАЗЫ ЗНАНИЙ RAG - ПОСЛЕДНЯЯ ПАРТИЯ")
